"""Classroom view of geographic model evidence and the review-capacity tradeoff."""

PAGE = r'''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>Geographic model performance</title><style>
:root{font:15px system-ui;color:#183c32;background:#f6f8f5}*{box-sizing:border-box}body{margin:0}main{padding:26px 30px;max-width:1440px;margin:auto}h1{font-size:27px;letter-spacing:-.7px;margin:0 0 9px}h2{font-size:18px;margin:0 0 12px}p{line-height:1.55}.eyebrow{text-transform:uppercase;letter-spacing:1.6px;font-size:11px;font-weight:700;color:#526b60}.intro{max-width:850px;color:#52655c;margin:0 0 18px}.scope{padding:13px 16px;background:#fff1d9;border-left:3px solid #b37425;font-size:13px}.summary{display:grid;grid-template-columns:repeat(4,1fr);border-block:1px solid #cbd6cd;margin:23px 0}.metric{padding:18px 20px 18px 0}.metric strong{display:block;font-size:30px;font-weight:650;letter-spacing:-1px}.metric span{font-size:12px;color:#52655c}.workspace{display:grid;grid-template-columns:minmax(400px,1.5fr) minmax(280px,1fr);gap:30px}.controls{display:flex;flex-wrap:wrap;gap:15px;margin:20px 0}label{font-size:12px;display:block}select,input{font:inherit;margin-top:6px}select{display:block;padding:8px;border:1px solid #aebfb3;border-radius:4px;background:white;color:inherit}select:focus-visible,a:focus-visible,button:focus-visible{outline:3px solid #bd762b;outline-offset:2px}.map-wrap{background:#e9efe8;border:1px solid #d0dcd0;padding:12px}svg{display:block;width:100%;height:370px}.legend{font-size:12px;color:#52655c;display:flex;gap:18px;flex-wrap:wrap;margin-top:9px}.swatch{display:inline-block;width:10px;height:10px;background:#1c6d54;margin-right:5px}.truth{background:#d17620;border-radius:50%}.detail{min-height:68px;font-size:13px;color:#435e50}table{border-collapse:collapse;width:100%;font-size:12px;font-variant-numeric:tabular-nums}th,td{text-align:right;padding:11px 7px;border-bottom:1px solid #d5dfd6}th:first-child,td:first-child{text-align:left}th{font-weight:600;color:#53675b}caption{text-align:left;font-size:13px;color:#53675b;margin-bottom:8px}.selected{background:#e8f0e8}.comparison{overflow:auto;margin-top:28px}.caption{font-size:12px;color:#52655c}a{color:#175a43}#error{color:#932a22}details{border-top:1px solid #d5dfd6;padding:15px 0;margin-top:18px}summary{cursor:pointer;font-weight:600}#decision{line-height:1.6}#budget-note{min-height:45px}button{font:inherit;cursor:pointer;color:#183c32;background:#fff;border:1px solid #aebfb3;border-radius:4px;padding:8px 12px}button:disabled{opacity:.5;cursor:default}@media(max-width:850px){main{padding:20px 16px}.workspace{grid-template-columns:1fr}.summary{grid-template-columns:1fr 1fr}.metric strong{font-size:26px}svg{height:300px}}@media(prefers-reduced-motion:no-preference){.metric strong{transition:color .15s}}
</style><main><div class="eyebrow">Ignition research · geographic transfer</div><h1>Geographic ignition performance</h1>
<p class="intro">Compare lightning features and simpler models with physical constraints on the same held-out development geography. Each example is a 10 km grid cell on one day.</p>
<p class="scope">Previously exposed 2017 development data. The 92 examples are positive cell-days, not 92% accuracy or necessarily 92 unique fires. Live prediction remains unavailable.</p>
<p id="status" role="status">Loading verified experiment results…</p><p id="error" role="alert"></p>
<section id="results" hidden><div class="controls"><label>Development candidate<select id="candidate"><option value="reference">Reference · weather and terrain</option><option value="lightning_24h">Reference + past 24h lightning</option><option value="lightning_24h_168h">Reference + past 24h / 7d lightning</option><option value="physical_logistic">Physical features · logistic regression</option><option value="physical_monotonic">Physical features · constrained boosting</option></select></label><label>Daily review capacity<select id="budget"><option value="1">1% · registered comparison</option><option value="2">2% · sensitivity only</option><option value="5">5% · sensitivity only</option><option value="10">10% · sensitivity only</option><option value="20">20% · sensitivity only</option></select></label></div>
<div class="summary" aria-live="polite"><div class="metric"><strong id="hits">—</strong><span>Prioritized positive cell-days</span></div><div class="metric"><strong id="misses">—</strong><span>Missed positive cell-days</span></div><div class="metric"><strong id="recall">—</strong><span>Recall at selected capacity</span></div><div class="metric"><strong id="precision">—</strong><span>Precision of review list</span></div></div>
<div class="workspace"><section><h2>Geographic development replay</h2><div class="controls"><label>Recorded date<select id="day"></select></label><button id="next" type="button">Next date</button><label><input type="checkbox" id="truth" checked> Show recorded starts</label></div><div class="map-wrap"><svg id="map" viewBox="0 0 900 520" role="img" aria-label="Held-out geographic grid and daily review selection"></svg></div><div class="legend"><span><i class="swatch"></i>Prioritized cells</span><span><i class="swatch" style="background:#c4d2c6"></i>Other evaluated cells</span><span><i class="swatch truth"></i>Recorded start</span></div><p class="detail" id="cell-detail" aria-live="polite">Select a grid cell to inspect its saved probability and rank.</p><p class="caption">Projected grid schematic in EPSG:3978. Gaps are outside this development subgroup. Recorded labels are shown for evaluation and were not used as same-day predictors.</p></section>
<section><h2>Coverage comes with review workload</h2><p id="budget-note"></p><table><caption>Whole-season cell-day review slots</caption><thead><tr><th>Capacity</th><th>Found</th><th>Missed</th><th>False positives*</th></tr></thead><tbody id="capacity"></tbody></table><p class="caption">*Review slots without a recorded ignition label. Archive completeness is imperfect; an unlabelled cell-day is not verified fire absence. Widening the list changes workload, not model skill.</p><details open><summary>Candidate decision</summary><p id="decision"></p></details><details><summary>What this demo establishes</summary><p>Lightning features use only completed three-hour observation bins before the local issue time. Candidate selection used the earlier 2014/2015 folds; calibration used 2016 training geography. This 2017 diagnostic was already exposed and cannot establish new unseen generalization.</p><p>Reported active fires, ignition probabilities and historical spread reconstructions are separate outputs. Predicting an ignition cause and issuing public warnings are not implemented.</p></details></section></div>
<section class="comparison"><h2>Matched geographic comparison · fixed 1% daily capacity</h2><table><thead><tr><th>Candidate</th><th>Found</th><th>Recall</th><th>Average precision</th><th>Brier score</th><th>Log loss</th></tr></thead><tbody id="comparison"></tbody></table><p class="caption" id="provenance"></p></section></section></main>
<script>
const el=id=>document.getElementById(id),names={reference:'Reference',lightning_24h:'+ 24h lightning',lightning_24h_168h:'+ 24h / 7d lightning',physical_logistic:'Physical · logistic',physical_monotonic:'Physical · constrained boosting'};
let evidence=null,currentCells=null,requestNumber=0;
const fmt=x=>Number(x).toLocaleString('en-CA'),pct=x=>(100*x).toFixed(2)+'%';
function addRow(target,values,highlight=false){const row=document.createElement('tr');if(highlight)row.className='selected';for(const value of values){const td=document.createElement('td');td.textContent=value;row.appendChild(td)}el(target).appendChild(row)}
async function get(url){const response=await fetch(url,{signal:AbortSignal.timeout(20000)});const data=await response.json();if(!response.ok)throw Error(data.message||'Saved experiment evidence is unavailable.');return data}
function updateSummary(){
 const candidate=el('candidate').value,budget=Number(el('budget').value),curves=evidence.capacity_curves.inner_spatial[candidate],chosen=curves.find(x=>x.budget_percent===budget);
 el('hits').textContent=chosen.hits+' / '+chosen.positives;el('misses').textContent=chosen.misses;el('recall').textContent=pct(chosen.recall);el('precision').textContent=pct(chosen.precision);
 el('budget-note').textContent=fmt(chosen.alerts)+' review slots across 184 dates; '+fmt(chosen.false_positives)+' have no recorded start label. '+(budget===1?'This is the registered comparison capacity.':'Sensitivity view: this changes the review budget; it is not a model improvement.');
 el('capacity').replaceChildren();for(const row of curves)addRow('capacity',[row.budget_percent+'%',row.hits,row.misses,fmt(row.false_positives)],row.budget_percent===budget);
 el('comparison').replaceChildren();for(const row of evidence.results.filter(x=>x.protocol==='inner_spatial'))addRow('comparison',[names[row.candidate],row.hits+' / '+row.positives,pct(row.daily_budget_recall),row.average_precision.toFixed(6),row.brier.toExponential(3),row.log_loss.toFixed(6)],row.candidate===candidate);
 const selected=evidence.selected.inner_spatial,passed=evidence.development_gates_pass.inner_spatial;
 el('decision').textContent='Frozen earlier-fold choice: '+names[selected]+'. '+(passed?'It passed the registered development gate; an untouched evaluation and live-input qualification are still required.':'The full development gate did not pass. Existing serving models are retained.')+' No candidate is promoted to live forecasting.';
 if(currentCells)drawMap(currentCells);
}
function drawMap(data){
 const svg=el('map');svg.replaceChildren();const rows=data.rows,ns='http://www.w3.org/2000/svg',budget=Math.ceil(rows.length*Number(el('budget').value)/100),truth=el('truth').checked;
 const xs=rows.map(x=>x.x),ys=rows.map(x=>x.y),minX=Math.min(...xs),maxY=Math.max(...ys)+10000,spanX=Math.max(...xs)-minX+10000,spanY=maxY-Math.min(...ys),scale=Math.min(850/spanX,470/spanY),offsetX=(900-spanX*scale)/2,offsetY=20;
 for(const cell of rows){const x=offsetX+(cell.x-minX)*scale,y=offsetY+(maxY-cell.y-10000)*scale,side=10000*scale,rect=document.createElementNS(ns,'rect');rect.setAttribute('x',x);rect.setAttribute('y',y);rect.setAttribute('width',Math.max(1,side-.3));rect.setAttribute('height',Math.max(1,side-.3));rect.setAttribute('fill',cell.rank<=budget?'#1c6d54':'#c4d2c6');rect.setAttribute('tabindex','0');rect.setAttribute('role','button');rect.setAttribute('aria-label',cell.grid_id+', rank '+cell.rank);
 const inspect=()=>{el('cell-detail').textContent=cell.grid_id+' · '+data.date+' · probability '+(100*cell.probability).toFixed(6)+'% · rank '+cell.rank+' / '+rows.length+' · '+(cell.rank<=budget?'prioritized':'outside review list')+(truth?' · recorded start: '+(cell.ignition?'yes':'no'):'')};rect.onclick=inspect;rect.onfocus=inspect;rect.onkeydown=event=>{if(event.key==='Enter'||event.key===' '){event.preventDefault();inspect()}};svg.appendChild(rect);
 if(truth&&cell.ignition){const dot=document.createElementNS(ns,'circle');dot.setAttribute('cx',x+side/2);dot.setAttribute('cy',y+side/2);dot.setAttribute('r',Math.max(3,side*.38));dot.setAttribute('fill','#d17620');dot.setAttribute('stroke','#fff');dot.setAttribute('stroke-width','1');dot.style.pointerEvents='none';svg.appendChild(dot)}
 }
 el('cell-detail').textContent=data.date+' · '+rows.length+' evaluated cells · '+data.positives+' recorded positive cell-days. Select a cell for its saved score.';
}
async function loadMap(){const number=++requestNumber;currentCells=null;el('map').replaceChildren();el('cell-detail').textContent='Loading saved geographic scores…';el('error').textContent='';try{const data=await get('/api/model-evidence/cells?'+new URLSearchParams({candidate:el('candidate').value,date:el('day').value}));if(number!==requestNumber)return;currentCells=data;drawMap(data)}catch(error){if(number!==requestNumber)return;el('error').textContent=error.message;el('cell-detail').textContent='Geographic scores unavailable.'}}
el('candidate').onchange=()=>{updateSummary();loadMap()};el('budget').onchange=updateSummary;el('truth').onchange=()=>{if(currentCells)drawMap(currentCells)};el('day').onchange=loadMap;
el('next').onclick=()=>{el('day').selectedIndex=(el('day').selectedIndex+1)%el('day').options.length;loadMap()};
(async()=>{try{evidence=await get('/api/model-evidence');const available=new Set(evidence.results.filter(x=>x.protocol==='inner_spatial').map(x=>x.candidate));for(const option of [...el('candidate').options])if(!available.has(option.value))option.remove();el('candidate').value=evidence.selected.inner_spatial;for(const date of evidence.dates){const option=document.createElement('option');option.value=date;option.textContent=date;el('day').appendChild(option)}el('day').value='2017-08-09';el('provenance').textContent=evidence.experiments.join(' + ')+' · '+evidence.created_at_utc+' · '+evidence.model_fits+' fits · protected prior results unchanged.';el('status').textContent='Saved development experiments loaded. No live predictions.';el('results').hidden=false;updateSummary();await loadMap()}catch(error){el('status').textContent='Model experiment is not ready to display.';el('error').textContent=error.message}})();
</script></html>'''
